#pragma once
#include <cstddef>

namespace inkle {

// Packed, sorted five-letter word lists generated by tools/inkle/gen_words.py.
// Each word occupies exactly WORD_LEN bytes with no terminator; the arrays live
// in flash and are only ever read through binary search or by index.
constexpr size_t WORD_LEN = 5;

extern const size_t ANSWER_COUNT;
extern const size_t ALLOWED_COUNT;
extern const char ANSWERS[];
extern const char ALLOWED[];

}  // namespace inkle
